insert into app.interview_turns (interview_id, turn_order, topic, question, answer, answer_evaluation) values ('4de7d44e-81fc-3a5d-de02-fc3ef90a32b7', 1, 'Plataforma', 'Sobre «Kubernetes en producción»: cuéntame el proyecto más exigente en el que lo aplicaste y cuál fue tu papel.', 'Operé clústeres de AKS en producción durante 4 años, con más de 40 servicios. Lo documenté para el equipo.', 'match');
