insert into app.interview_turns (interview_id, turn_order, topic, question, answer, answer_evaluation) values ('4de7d44e-81fc-3a5d-de02-fc3ef90a32b7', 3, 'Infraestructura como código', 'Sobre «Terraform»: cuéntame el proyecto más exigente en el que lo aplicaste y cuál fue tu papel.', 'Infraestructura como código con Terraform en tres ambientes. Lo hice con otra persona del equipo.', 'match');
insert into app.interview_turns (interview_id, turn_order, topic, question, answer, answer_evaluation) values ('4de7d44e-81fc-3a5d-de02-fc3ef90a32b7', 4, 'Idiomas', 'Sobre «Inglés B2»: cuéntame el proyecto más exigente en el que lo aplicaste y cuál fue tu papel.', 'Inglés B2, reuniones diarias con un equipo en Estados Unidos. Fue mi primer proyecto en ese cargo.', 'match');
